onArrival.$code:
if (Q.month_actions > 0) { Q.month_actions -= 1; }
var card = this.state.lastPlayedCard;
card.image = card.cardImage;
if (Q.difficulty >= 0 && (!Q.deck_size || Q.deck_size == 3)) {
    this.state.currentHands['main'].push(card);
} else {
    this.state.currentHands['main.main_easy'].push(card);
}
if (Q[card.id + "_timer"]) { Q[card.id + "_timer"] = 0; }
if (this.state.visits[card.id]) { this.state.visits[card.id] -= 1; }

// normaliza el voto de cada grupo social (0 a 100)
for (var c of Q.classes) {
    var class_votes = 0;
    for (var party of Q.parties) {
        if (Q[c+'_'+party] < 0) { Q[c+'_'+party] = 0; }
        class_votes += Q[c+'_'+party];
    }
    for (var party of Q.parties) {
        Q[c+'_'+party+'_normalized'] = 100*Q[c+'_'+party]/class_votes;
        Q[c+'_'+party+'_display'] = Math.round(100*Q[c+'_'+party]/class_votes);
    }
}
// apoyo total por partido
var total_support = 0;
for (var party of Q.parties) {
    var ps = 0;
    for (var c of Q.classes) { ps += Q[c]*Q[c+'_'+party+'_normalized']; }
    Q[party+'_support'] = ps;
    total_support += ps;
}
for (var party of Q.parties) {
    Q[party+'_normalized'] = Q[party+'_support']/total_support;
    Q[party+'_votes'] = Math.round(Q[party+'_normalized']*100);
}

if (Q.n_elections < 2) { Q.next_election_year = 1933; Q.next_election_month = 11; }
else { Q.next_election_month = Q.month + 3; Q.next_election_year = Q.year; if (Q.next_election_month > 12) { Q.next_election_month -= 12; Q.next_election_year += 1; } }
Q.in_election = 1;

if (Q.advisor_action_timer <= 0) {
    Q.pinnedCardsDescription = 'Asesores - hay una acción disponible.';
} else if (Q.advisor_action_timer == 1) {
    Q.pinnedCardsDescription = 'Asesores - próxima acción disponible en 1 mes.';
} else {
    Q.pinnedCardsDescription = 'Asesores - próxima acción disponible en ' + Q.advisor_action_timer + ' meses.';
}

Q.last_advisor_action = 0;

for (var c of Q.classes) { for (var party of Q.parties) { if (Q[c+'_'+party] < 0) { Q[c+'_'+party] = 0; } } }
Q.pro_republic = Math.round(Q.pro_republic);
Q.nationalism = Math.round(Q.nationalism);
Q.socialism = Math.round(Q.socialism);
if (Q.pro_republic < 0) { Q.pro_republic = 0; }
if (Q.pro_republic >= 100) { Q.pro_republic = 99; }
if (Q.religious_tension < 0) { Q.religious_tension = 0; }
if (Q.coup_progress < 0) { Q.coup_progress = 0; }
if (Q.coalition_dissent < 0) { Q.coalition_dissent = 0; }
for (var k of ['izq','rad','cen','per','pce','cnt','ceda']) { if (Q[k+'_relation'] < 0) { Q[k+'_relation'] = 0; } if (Q[k+'_relation'] > 100) { Q[k+'_relation'] = 100; } }

// recalcula el apoyo
for (var c of Q.classes) {
    var class_votes = 0;
    for (var party of Q.parties) { class_votes += Q[c+'_'+party]; }
    for (var party of Q.parties) {
        Q[c+'_'+party+'_normalized'] = 100*Q[c+'_'+party]/class_votes;
        Q[c+'_'+party+'_display'] = Math.round(100*Q[c+'_'+party]/class_votes);
    }
}
var total_support = 0;
for (var party of Q.parties) {
    var ps = 0;
    for (var c of Q.classes) { ps += Q[c]*Q[c+'_'+party+'_normalized']; }
    Q[party+'_support'] = ps;
    total_support += ps;
}
for (var party of Q.parties) {
    Q[party+'_normalized'] = Q[party+'_support']/total_support;
    Q[party+'_votes'] = Math.round(Q[party+'_normalized']*100);
}

// disenso interno
for (var c of Q.factions) {
    if (Q[c+'_dissent'] < 0) { Q[c+'_dissent'] = 0; } else if (Q[c+'_dissent'] >= 100) { Q[c+'_dissent'] = 99; }
    if (Q[c+'_strength'] < 0) { Q[c+'_strength'] = 0; }
}
if (Q.unemployed <= 1) { Q.unemployed = 1; }
var total_strength = 0;
for (var c of Q.factions) { total_strength += Q[c+'_strength']; }
for (var c of Q.factions) { Q[c+'_strength'] = 100*Q[c+'_strength']/total_strength; }
var total_dissent = 0;
for (var c of Q.factions) { total_dissent += Q[c+'_strength']*Q[c+'_dissent']; }
Q.dissent = 0.01*total_dissent/100;
Q.dissent_percent = Q.dissent*100;
if (Q.dissent < 0) { Q.dissent = 0; } else if (Q.dissent > 0.95) { Q.dissent = 0.95; }

if (Q.month_actions >= 1) {
    Q.time += 1;
    Q.month_actions = 0;
    Q.month += 1;
    if (Q.month >= 13) { Q.month = 1; Q.year += 1; }
    for (var timer of Q.timers) {
        if (Q[timer+'_timer'] && Q[timer+'_timer'] > 0) { Q[timer+'_timer'] -= 1; }
    }
    // economía: curva de Phillips simplificada
    if (Q.budget <= 0 && Q.budget > -2 && Q.inflation < 2.5) { Q.inflation += 0.1; }
    if (Q.budget <= -2 && Q.inflation < 6) { Q.inflation += 0.2; }
    if (Q.inflation < -0.5 && Q.unemployed < 15) { Q.unemployed += 0.2; }
    if (Q.economic_growth < -0.5 && Q.unemployed <= 18) { Q.unemployed += 0.1; }
    if (Q.economic_growth >= 2 && Q.unemployed >= 12) { Q.unemployed -= 0.1; }
    if (Q.economic_growth >= 4 && Q.unemployed >= 6) { Q.unemployed -= 0.1; }
    if (Q.economic_growth >= 7) { Q.economic_growth -= 0.2; }
    if (Q.works_program >= 2 && Q.economic_growth < 3) { Q.economic_growth += 0.1; }

    // opinión según la economía
    if (Q.unemployed > 12 && Q.pro_republic > 40) { Q.pro_republic -= 1; }
    if (Q.religious_tension >= 6 && Q.pro_republic > 35) { Q.pro_republic -= 0.5; }
    if (Q.school_program >= 2 && Q.pro_republic < 60) { Q.pro_republic += 0.4; }

    // el desgaste de la República según su apoyo
    if (Q.regime >= 1 && Q.pro_republic < (Q.psoe_votes + Q.izq_votes + Q.rad_votes + Q.cen_votes - 12)) {
        if (Q.medias_psoe > 0) { Q.medias_psoe -= 3/12; Q.medias_fal += 1/12; }
        if (Q.propietarios_izq > 0) { Q.propietarios_izq -= 3/12; Q.propietarios_ceda += 2/12; }
        if (Q.catolicos_cen > 0) { Q.catolicos_cen -= 3/12; Q.catolicos_ceda += 2/12; }
    }

    // deriva anual de apoyos (polarización)
    if (Q.year == 1930) {
        Q.medias_izq += 2/12; Q.medias_rad += 1/12;
        Q.obreros_psoe += 2/12; Q.jornaleros_psoe += 2/12;
    } else if (Q.year == 1931) {
        Q.jornaleros_psoe += 2/12; Q.obreros_psoe += 1/12;
        Q.catolicos_ceda += 2/12; Q.propietarios_ceda += 2/12;
        Q.unemployed += 4/12;
        if (Q.land_reform < 1) { Q.jornaleros_abst += 3/12; Q.jornaleros_pce += 1/12; }
    } else if (Q.year == 1932) {
        Q.unemployed += 3/12;
        Q.catolicos_ceda += 4/12; Q.propietarios_ceda += 4/12; Q.propietarios_mon += 2/12;
        Q.medias_rad -= 2/12; Q.medias_izq -= 2/12;
        Q.req_strength += 20/12;
        if (Q.land_reform < 1) { Q.jornaleros_abst += 5/12; Q.jornaleros_pce += 2/12; Q.obreros_abst += 2/12; }
        if (Q.land_reform >= 1 && Q.coalition_dissent >= 2) { Q.propietarios_ceda += 3/12; }
        if (!Q.works_program) { Q.unemployed_abst += 3/12; Q.unemployed_pce += 1/12; Q.unemployed_fal += 1/12; }
    } else if (Q.year == 1933) {
        Q.catolicos_ceda += 6/12; Q.propietarios_ceda += 6/12; Q.medias_ceda += 3/12;
        Q.medias_rad += 2/12; Q.medias_izq -= 3/12;
        Q.obreros_abst += (Q.cnt_pact ? 0 : 5/12);
        Q.jornaleros_abst += (Q.cnt_pact ? 0 : 6/12);
        Q.req_strength += 20/12; Q.fal_strength += 2/12;
        Q.unemployed_fal += 2/12; Q.medias_fal += 2/12;
    } else if (Q.year == 1934) {
        Q.catolicos_ceda += 3/12; Q.propietarios_ceda += 3/12;
        Q.obreros_pce += 4/12; Q.unemployed_pce += 3/12; Q.obreros_psoe += 2/12;
        Q.fal_strength += 6/12; Q.medias_fal += 4/12; Q.propietarios_fal += 4/12;
        Q.req_strength += 20/12;
    } else if (Q.year >= 1935) {
        Q.obreros_pce += 3/12; Q.unemployed_pce += 3/12;
        Q.medias_fal += 5/12; Q.propietarios_fal += 5/12; Q.catolicos_fal += 3/12;
        Q.fal_strength += 15/12; Q.req_strength += 20/12;
        Q.medias_izq += 3/12; Q.obreros_psoe += 2/12; Q.jornaleros_psoe += 3/12;
    }
    if (Q.regime >= 1 && Q.coup_progress > 0 && Q.pro_republic >= 45) { Q.coup_progress -= 0.1; }
    if (Q.regime >= 1 && Q.coup_progress > 0 && Q.army_loyalty >= 0.5) { Q.coup_progress -= 0.1; }
    if (Q.army_loyalty > 0.95) { Q.army_loyalty = 0.95; }
    if (Q.army_loyalty < 0.02) { Q.army_loyalty = 0.02; }
    if (Q.gc_loyalty > 0.95) { Q.gc_loyalty = 0.95; }
    if (Q.gc_loyalty < 0.02) { Q.gc_loyalty = 0.02; }
    if (Q.ga_loyalty > 0.95) { Q.ga_loyalty = 0.95; }
    if (Q.js_banned) { Q.js_strength = Math.max(0, Q.js_strength - 1); }
    // la crisis financiera mundial se deja sentir tarde
    if (Q.year == 1931 || Q.year == 1932) { Q.economic_growth -= 0.1; }
}
Q.has_event = 0;
var scene = this.game.scenes['post_event.events_choice'];
var choices = this._compileChoices(scene);
if (choices && choices[0].title != "Continue...") { Q.has_event = 1; } else { Q.has_event = 0; }

Q['next_election_time'] = ((Q['time'] || 0) + (Q['time_to_election'] || 0));
Q['next_election_month'] = ((Q['month'] || 0) + (Q['time_to_election'] || 0));
Q['next_election_year'] = (Q['year'] || 0);
 if (((Q['next_election_month'] || 0) > 12) ) { Q['next_election_year'] = (Q['next_election_year'] || 0) + 1; } 
 if (((Q['next_election_month'] || 0) > 12) ) { Q['next_election_month'] = (Q['next_election_month'] || 0) - 12; }

Q.unemployed_2 = Q.unemployed.toFixed(1);
Q.inflation_2 = Q.inflation.toFixed(1);
Q.economic_growth_2 = Q.economic_growth.toFixed(1);

Q['advisor_action_timer'] = 6;
Q['last_advisor_action'] = 1;
Q['izquierda_strength'] = (Q['izquierda_strength'] || 0) + 6;
Q['izquierda_dissent'] = (Q['izquierda_dissent'] || 0) - 5;
Q['radicalization'] = (Q['radicalization'] || 0) + 1;
Q['obreros_psoe'] = (Q['obreros_psoe'] || 0) + 3;

Q['advisor_action_timer'] = 6;
Q['last_advisor_action'] = 1;
Q['izquierda_dissent'] = (Q['izquierda_dissent'] || 0) - 8;
Q['caballerista_dissent'] = (Q['caballerista_dissent'] || 0) - 5;
Q['prietista_dissent'] = (Q['prietista_dissent'] || 0) - 5;
Q['besteirista_dissent'] = (Q['besteirista_dissent'] || 0) - 10;
Q['intelectual_dissent'] = (Q['intelectual_dissent'] || 0) - 3;

Q['advisor_action_timer'] = 6;
Q['last_advisor_action'] = 1;
Q['obreros_psoe'] = (Q['obreros_psoe'] || 0) + 4;
Q['jornaleros_psoe'] = (Q['jornaleros_psoe'] || 0) + 3;
Q['coalition_dissent'] = (Q['coalition_dissent'] || 0) + 1;
Q['radicalization'] = (Q['radicalization'] || 0) + 1;
Q['coup_progress'] = (Q['coup_progress'] || 0) + 1;
Q['caballerista_strength'] = (Q['caballerista_strength'] || 0) + 3;

Q['advisor_action_timer'] = 6;
Q['last_advisor_action'] = 1;
Q['medias_psoe'] = (Q['medias_psoe'] || 0) + 3;
Q['obreros_psoe'] = (Q['obreros_psoe'] || 0) + 2;
Q['catolicos_psoe'] = (Q['catolicos_psoe'] || 0) + 1;
Q['intelectual_strength'] = (Q['intelectual_strength'] || 0) + 2;

Q['advisor_action_timer'] = 6;
Q['last_advisor_action'] = 1;
Q['pro_republic'] = (Q['pro_republic'] || 0) + 3;
Q['intelectual_strength'] = (Q['intelectual_strength'] || 0) + 3;
Q['medias_psoe'] = (Q['medias_psoe'] || 0) + 2;

Q['advisor_action_timer'] = 6;
Q['last_advisor_action'] = 1;
Q['economic_growth'] = (Q['economic_growth'] || 0) + 0.5;
Q['intelectual_strength'] = (Q['intelectual_strength'] || 0) + 3;
Q['medias_psoe'] = (Q['medias_psoe'] || 0) + 2;

Q['advisor_action_timer'] = 6;
Q['last_advisor_action'] = 1;
Q['izq_relation'] = (Q['izq_relation'] || 0) + 8;
Q['rad_relation'] = (Q['rad_relation'] || 0) + 5;
Q['cen_relation'] = (Q['cen_relation'] || 0) + 5;
Q['collaboration'] = (Q['collaboration'] || 0) + 1;
Q['izquierda_dissent'] = (Q['izquierda_dissent'] || 0) + 4;

Q['negrin_advisor'] = 1;
 if ((((Q['radicalization'] || 0) >= 2) || ((Q['revolution_support'] || 0) >= 2)) ) { Q['araquistain_advisor'] = 1; } 
Q['n_advisors'] = (Q['n_advisors'] || 0) + 1;

Q['conjuncion_alliance'] = 1;
Q['izq_relation'] = (Q['izq_relation'] || 0) + 6;
Q['rad_relation'] = (Q['rad_relation'] || 0) + 3;
Q['pro_republic'] = (Q['pro_republic'] || 0) + 4;
Q['medias_psoe'] = (Q['medias_psoe'] || 0) + 3;
Q['obreros_psoe'] = (Q['obreros_psoe'] || 0) + 2;
Q['besteirista_dissent'] = (Q['besteirista_dissent'] || 0) + 4;
Q['izquierda_dissent'] = (Q['izquierda_dissent'] || 0) + 4;

Q['pro_republic'] = (Q['pro_republic'] || 0) + 1;
Q['cnt_relation'] = (Q['cnt_relation'] || 0) + 6;
Q['ga_loyalty'] = (Q['ga_loyalty'] || 0) - 0.03;
Q['gc_loyalty'] = (Q['gc_loyalty'] || 0) - 0.02;
Q['izq_relation'] = (Q['izq_relation'] || 0) - 3;
Q['jornaleros_abst'] = (Q['jornaleros_abst'] || 0) - 3;
Q['coalition_dissent'] = (Q['coalition_dissent'] || 0) + 1;
 if (((Q['cnt_relation'] || 0) >= 30) ) { Q['cnt_pact'] = (Q['cnt_pact'] || 0) + 1; }

Q['psoe_in_government'] = 0;
Q['in_conjuncion'] = 0;
Q['go_alone'] = 1;
Q['radicalization'] = (Q['radicalization'] || 0) + 2;
Q['caballerista_strength'] = (Q['caballerista_strength'] || 0) + 6;
Q['izquierda_strength'] = (Q['izquierda_strength'] || 0) + 4;
Q['prietista_dissent'] = (Q['prietista_dissent'] || 0) + 12;
Q['besteirista_dissent'] = (Q['besteirista_dissent'] || 0) + 8;
Q['obreros_psoe'] = (Q['obreros_psoe'] || 0) + 4;
Q['jornaleros_psoe'] = (Q['jornaleros_psoe'] || 0) + 3;
Q['medias_psoe'] = (Q['medias_psoe'] || 0) - 4;
Q['medias_izq'] = (Q['medias_izq'] || 0) + 2;
Q['propietarios_ceda'] = (Q['propietarios_ceda'] || 0) + 2;
Q['izq_relation'] = (Q['izq_relation'] || 0) - 8;
Q['rad_relation'] = (Q['rad_relation'] || 0) - 8;
Q['prime_minister'] = "Lerroux";
Q['prime_minister_party'] = "Radical";
Q['president'] = "Alcalá-Zamora";

Q['pro_republic'] = (Q['pro_republic'] || 0) + 3;
Q['church_reform'] = (Q['church_reform'] || 0) + 1;
Q['religious_tension'] = (Q['religious_tension'] || 0) + 2;
Q['catolicos_ceda'] = (Q['catolicos_ceda'] || 0) + 4;
Q['catolicos_psoe'] = (Q['catolicos_psoe'] || 0) - 2;
Q['coup_progress'] = (Q['coup_progress'] || 0) + 1;
Q['womens_vote'] = 1;
Q['intelectual_strength'] = (Q['intelectual_strength'] || 0) + 4;
Q['campoamor_advisor'] = 1;
Q['cen_relation'] = (Q['cen_relation'] || 0) - 8;
Q['izquierda_dissent'] = (Q['izquierda_dissent'] || 0) - 3;

// puntuación de las fuerzas leales
var loyal = Q.army_loyalty*45 + Q.gc_loyalty*20 + Q.ga_strength*1.2 + Q.pro_republic*0.15 + Q.js_strength*0.25;
if (Q.october_choice == 2) { loyal += 4; }
if (Q.cnt_pact >= 1) { loyal += 4; }
if (Q.frente_popular && Q.in_frente_popular) { loyal += 4; }
if (Q.coup_failed) { loyal += 5; }
var rebel = Q.coup_progress*3.2 + Q.req_strength*0.3 + Q.fal_strength*0.3 + 15;
if (Q.army_reform >= 2) { rebel -= 4; }
if (Q.fascist_urgency >= 5) { rebel -= 3; }
Q.loyal_score = Math.round(loyal);
Q.rebel_score = Math.round(rebel);
if (loyal >= rebel + 4) { Q.coup_outcome = 'fail'; }
else if (loyal >= rebel - 4) { Q.coup_outcome = 'civil_war'; }
else { Q.coup_outcome = 'success'; }

Q['budget'] = (Q['budget'] || 0) - 1;
Q['works_program'] = (Q['works_program'] || 0) + 2;
Q['unemployed'] = (Q['unemployed'] || 0) - 2;
Q['economic_growth'] = (Q['economic_growth'] || 0) + 1;
Q['unemployed_psoe'] = (Q['unemployed_psoe'] || 0) + 4;
Q['obreros_psoe'] = (Q['obreros_psoe'] || 0) + 3;
Q['prietista_strength'] = (Q['prietista_strength'] || 0) + 3;
Q['capital_strike_progress'] = (Q['capital_strike_progress'] || 0) + 1;

// la abstención anarquista no vota: se excluye
var votes = {};
var tot = 0;
for (var p of Q.parties) { if (p != 'abst') { votes[p] = Q[p+'_normalized']; tot += votes[p]; } }
for (var p in votes) { votes[p] = votes[p]/tot; }

// definición de bloques según alianzas
var bloc_left = ['psoe', 'izq'];
var bloc_right = ['ceda', 'mon', 'fal', 'otros'];
if (Q.n_elections == 1) {
    // 1931: Conjunción republicano-socialista
    bloc_left = bloc_left.concat(['rad', 'cen']);
} else if (Q.n_elections == 2) {
    // 1933: la Conjunción puede estar rota
    if (Q.go_alone) { bloc_right = bloc_right.concat(['rad', 'cen']); bloc_left = ['psoe']; }
    else { bloc_left = bloc_left.concat(['rad', 'cen']); }
} else {
    // 1936: Frente Popular contra Frente Nacional
    if (Q.frente_popular) { bloc_left = bloc_left.concat(['pce', 'per']); bloc_right = bloc_right.concat(['rad', 'cen']); }
    else { bloc_right = bloc_right.concat(['rad', 'cen']); }
}
var TL = 0; var TR = 0;
for (var p of bloc_left) { TL += votes[p]; }
for (var p of bloc_right) { TR += votes[p]; }
var winner = TL >= TR ? bloc_left : bloc_right;
var TW = TL >= TR ? TL : TR;
var loserTot = 1 - TW;
var seat = {};
var bonus = Q.electoral_bonus;
if (Q.n_elections == 1 && !Q.conjuncion_alliance) { bonus = bonus*0.5; }
if (TW >= 0.38 && TW < 0.8 && bonus > 0) {
    var newW = TW + bonus*(0.8 - TW);
    for (var p in votes) {
        if (winner.indexOf(p) >= 0) { seat[p] = votes[p]*newW/TW; }
        else { seat[p] = votes[p]*(1-newW)/loserTot; }
    }
    Q.winner_bonus = 1;
} else {
    for (var p in votes) { seat[p] = votes[p]; }
    Q.winner_bonus = 0;
}
Q.winning_bloc = TL >= TR ? 'izquierda' : 'derecha';
Q.bloc_left_share = Math.round(TL*100);
Q.bloc_right_share = Math.round(TR*100);

for (var p of Q.parties) { Q['old_'+p+'_r'] = Q[p+'_r']; }
var sum = 0;
for (var p in seat) {
    if (Q.electoral_threshold > 0 && votes[p]*100 < Q.electoral_threshold && p != 'otros') { seat[p] = 0; }
}
var s2 = 0; for (var p in seat) { s2 += seat[p]; }
for (var p in seat) { Q[p+'_r'] = Math.round(100*seat[p]/s2); sum += Q[p+'_r']; }
Q.otros_r += (100 - sum);
Q.abst_r = 0;
for (var p of Q.parties) {
    Q[p+'_seats'] = Math.round(Q[p+'_r']*4.7);
    Q['change_'+p+'_r'] = Q[p+'_r'] - Q['old_'+p+'_r'];
    var sign = Q['change_'+p+'_r'] > 0 ? '+' : '';
    Q['str_change_'+p] = sign + Q['change_'+p+'_r'];
}

// coaliciones posibles
Q.conjuncion_bloc = Q.psoe_r + Q.izq_r + Q.rad_r + Q.cen_r;
Q.left_bloc = Q.psoe_r + Q.izq_r + Q.per_r;
Q.frente_bloc = Q.psoe_r + Q.izq_r + Q.pce_r + Q.per_r;
Q.center_right_bloc = Q.rad_r + Q.cen_r + Q.ceda_r + Q.mon_r + Q.otros_r;
Q.right_bloc = Q.ceda_r + Q.mon_r + Q.fal_r + Q.otros_r;
Q.anti_republican_bloc = Q.mon_r + Q.fal_r;
Q.republican_center = Q.rad_r + Q.cen_r + Q.izq_r;
Q.leverage = Q.psoe_r;

// reiniciar el gobierno
Q.coalition_dissent = 0; Q.pce_coalition_dissent = 0;
Q.psoe_in_government = 0; Q.psoe_toleration = 0; Q.in_conjuncion = 0;
Q.in_frente_popular = 0; Q.in_republican_govt = 0; Q.in_psoe_majority = 0;
Q.regime = 2;

